$ErrorActionPreference='Stop';$base=Join-Path $PSScriptRoot '..';$runs=Join-Path $base 'runs';$out=Join-Path $base 'outputs';$rows=[System.Collections.Generic.List[object]]::new();$rawCols=@(0..31|ForEach-Object{'raw_f{0:d2}'-f $_});$normCols=@(0..31|ForEach-Object{'normalized_f{0:d2}'-f $_})
foreach($dir in Get-ChildItem -LiteralPath $runs -Directory){$file=Join-Path $dir.FullName 'model_features.csv';if(-not(Test-Path $file)){continue};$data=@(Import-Csv -LiteralPath $file);if($dir.Name -like 'er1024*' -or $dir.Name -like 'featurediag_er1024*'){$expected=10472}else{$expected=3968};$ids=[System.Collections.Generic.HashSet[string]]::new();$arcs=@{};$invalid=0;$predMin=[double]::PositiveInfinity;$predMax=[double]::NegativeInfinity;foreach($r in $data){[void]$ids.Add($r.edge_id);$arcs["$($r.source):$($r.target)"]=$r;foreach($c in $rawCols+$normCols){$v=[double]::Parse($r.$c,[Globalization.CultureInfo]::InvariantCulture);if([double]::IsNaN($v)-or[double]::IsInfinity($v)){$invalid++}};$p=[double]::Parse($r.prediction,[Globalization.CultureInfo]::InvariantCulture);if([double]::IsNaN($p)-or[double]::IsInfinity($p)-or$p-lt 0-or$p-gt 1){$invalid++};$predMin=[Math]::Min($predMin,$p);$predMax=[Math]::Max($predMax,$p)};$missing=0;$mismatch=0;foreach($r in $data){$rev=$arcs["$($r.target):$($r.source)"];if($null-eq$rev){$missing++;continue};foreach($c in $rawCols){if([double]::Parse($r.$c,[Globalization.CultureInfo]::InvariantCulture)-ne[double]::Parse($rev.$c,[Globalization.CultureInfo]::InvariantCulture)){$mismatch++;break}}};$rows.Add([pscustomobject]@{run=$dir.Name;rows=$data.Count;expected_directed_arcs=$expected;edge_ids_unique=$ids.Count;missing_reverse_arcs=$missing;reverse_raw_vector_mismatch=$mismatch;nonfinite_or_out_of_range_values=$invalid;prediction_min=$predMin;prediction_max=$predMax;pass=(($data.Count-eq$expected)-and($ids.Count-eq$expected)-and($missing-eq0)-and($mismatch-eq0)-and($invalid-eq0))})}
$rows|Export-Csv -NoTypeInformation -Encoding utf8 -LiteralPath (Join-Path $out 'feature_dump_audit.csv');$rows|Format-Table -AutoSize
